messages.content:
Tool response:
Tool: find_sales_orders
Description: Retrieve all sales orders from the Shopify sales channel with specific statuses and date range.
Parameters:
    {
      "type": "object",
      "properties": {
        "start_date": {
          "type": "string",
          "description": "Start date for filtering orders (YYYY-MM-DD)",
          "title": "Start Date"
        },
        "end_date": {
          "type": "string",
          "description": "End date for filtering orders (YYYY-MM-DD)",
          "title": "End Date"
        },
        "sales_channel": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter by sales channel name (e.g., 'Shopify')",
          "title": "Sales Channel"
        },
        "status": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter by order status (e.g., 'Unfulfilled', 'Partially Allocated')",
          "title": "Status"
        }
      },
      "required": [
        "start_date",
        "end_date"
      ]
    }
